import { isRecord } from "./record-shared.mjs";

export const UPDATE_COMPATIBILITY_CHUNK_HEADER =
  "// Generated by update-compat-inventory; do not edit.";

/** @param {string} source */
export function isUpdateCompatibilityChunk(source) {
  return source.startsWith(UPDATE_COMPATIBILITY_CHUNK_HEADER);
}

/**
 * @typedef {{ state: number, agent: number }} SchemaVersions
 * @param {unknown} value
 * @returns {SchemaVersions}
 */
export function requireUpdateCompatibilitySchemas(value) {
  if (
    !isRecord(value) ||
    typeof value.state !== "number" ||
    typeof value.agent !== "number" ||
    ![value.state, value.agent].every((version) => Number.isInteger(version) && version >= 0)
  ) {
    throw new Error(
      "Update compatibility requires recorded state and agent schema versions; refresh from exact package manifests",
    );
  }
  return { state: value.state, agent: value.agent };
}

/** @param {unknown} source @param {unknown} target */
export function updateCompatibilitySchemaReason(source, target) {
  const from = requireUpdateCompatibilitySchemas(source);
  const to = requireUpdateCompatibilitySchemas(target);
  return ["state", "agent"]
    .flatMap((kind) => {
      const key = /** @type {keyof SchemaVersions} */ (kind);
      return from[key] > to[key]
        ? [`${key} schema ${from[key]} exceeds candidate support ${to[key]}`]
        : [];
    })
    .join("; ");
}

/**
 * @template {{ version: string, schemaVersions?: SchemaVersions }} T
 * @param {{ schemaVersion: number, releases: T[] }} inventory
 * @param {unknown} target
 * @returns {T[]}
 */
export function supportedUpdateCompatibilityReleases(inventory, target) {
  // v2026.9.9 shipped v1 as an admitted-source list. Frozen artifacts retain that
  // contract; v2 is publication accounting and never guesses absent schema facts.
  if (inventory.schemaVersion === 1) {
    return inventory.releases;
  }
  if (inventory.schemaVersion !== 2) {
    throw new Error("Unsupported update compatibility inventory format");
  }
  return inventory.releases.filter(
    (release) => !updateCompatibilitySchemaReason(release.schemaVersions, target),
  );
}
